import math

def point_in_triangle(p, a, b, c):
    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])
    d1 = cross(a, b, p)
    d2 = cross(b, c, p)
    d3 = cross(c, a, p)
    has_neg = (d1 < 0) or (d2 < 0) or (d3 < 0)
    has_pos = (d1 > 0) or (d2 > 0) or (d3 > 0)
    if has_neg and has_pos:
        return False
    on_edge = False
    # Check whether p lies exactly on an edge
    # (t does not need to be strictly between 0 and 1 for this)
    def is_on_segment(o, a, p):
        # o -> a -> p and o -> p are allowed to be colinear
        if cross(o, a, p) != 0:
            return False
        if o[0] <= p[0] <= a[0] or a[0] <= p[0] <= o[0]:
            if o[1] <= p[1] <= a[1] or a[1] <= p[1] <= o[1]:
                return True
        return False
    if is_on_segment(a, b, p) or is_on_segment(b, c, p) or is_on_segment(c, a, p):
        on_edge = True
    return on_edge or not has_neg and not has_pos
```

