def classify_triangle_by_sides(p1, p2, p3):

    def square_distance(a, b):
        (x1, y1), (x2, y2) = a, b
        return (x1 - x2) ** 2 + (y1 - y2) ** 2

    s1 = square_distance(p1, p2)
    s2 = square_distance(p2, p3)
    s3 = square_distance(p3, p1)
    lengths = {s1, s2, s3}
    if len(lengths) == 1:
        return 'equilateral'
    elif len(lengths) == 2:
        return 'isosceles'
    else:
        return 'scalene'
```

