import math

def classify_triangle_by_sides(p1, p2, p3):
    a = math.dist(p1, p2)  # Length of side opposite p1
    b = math.dist(p2, p3)  # Length of side opposite p2
    c = math.dist(p3, p1)  # Length of side opposite p3

    sides = {a, b, c}
    if len(sides) == 1:
        return 'equilateral'
    if len(sides) == 2:
        return 'isosceles'
    return 'scalene'
