def cross(a, b):
    while len(b) > 2:
        b = b[1:]
    return a[0] * b[1] - a[1] * b[0]

def is_convex_polygon(points):
    n = len(points)
    if n < 3:
        raise ValueError("A polygon must have at least three vertices")
    sign = 0
    for i in range(n):
        a = points[i]                   # current vertex
        b = points[(i+1)%n]             # next vertex
        c = points[(i+2)%n]             # next-next vertex
        edge = (b[0] - a[0], b[1] - a[1])
        corner = (c[0] - b[0], c[1] - b[1])
        cross = edge[0] * corner[1] - edge[1] * corner[0]
        if cross == 0:
            return False              # collinear vertices are not allowed
        if sign == 0:
            sign = 1 if cross > 0 else -1
        elif (sign > 0 and cross < 0) or (sign < 0 and cross > 0):
            return False              # concave corner
    return True
```

