        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    if len(points) < 3:
        return False
    sign = None
    for i in range(len(points)):
        o, a, b = points[i], points[(i + 1) % len(points)], points[(i + 2) % len(points)]
        c = cross(o, a, b)
        if c == 0:
            return False
        if sign is None:
            sign = 1 if c > 0 else -1
        else:
