def is_convex_polygon(points):
    n = len(points)
    if n < 3:
        return False
    for i in range(n):
        a, b, c = points[i], points[(i + 1) % n], points[(i + 2) % n]
        cross = (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])
        if cross == 0:
            return False
        sign = cross > 0
        for j in range(i + 1, n):
            a, b, c = points[j], points[(j + 1) % n], points[(j + 2) % n]
            cross = (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])
            if cross == 0:
                return False
            if (cross > 0) != sign:
                return False
        return True
