    while grid:
        result.extend(grid[0])
        grid = grid[1:]
        if grid:
            for row in grid:
                result.append(row[-1])
                row.pop()
            if grid:
                result.extend(grid[-1][::-1])
                grid = grid[:-1]
                for row in grid:
                    result.append(row[0])
                    row.pop(0)
    return result
