from itertools import count
from copy import deepcopy


def equal_under_rotation(grid1, grid2):
    """Return True when a rotation of grid1 matches grid2 exactly."""

    def rotate(grid):
        """Return a copy of grid rotated 90 degrees clockwise."""
        m, n = len(grid), len(grid[0])
        return [[grid[m - j - 1][i] for j in range(m)] for i in range(n)]

    def same(grid1, grid2):
        """Return whether two grids are exactly equal."""
        return grid1 == grid2

    # empty grids are equal
    if not grid1 or not grid2:
        return True

    # match grid1 unchanged, then its three rotations
    for _ in count():
        if same(grid1, grid2):
            return True
        grid1 = rotate(deepcopy(grid1))
        if not grid1 or not grid2:
            return True
```

