def count_paths(grid):
    # If the start or end cell is blocked, no path exists.
    if grid[0][0] or grid[-1][-1]:
        return 0

    rows, cols = len(grid), len(grid[0])
    # dp[i][j] stores the number of paths to cell (i, j).
    dp = [[0] * cols for _ in range(rows)]
    dp[0][0] = 1  # One way to start at the top-left.

    # Fill in the first row and first column, as they have only one path each.
    for j in range(1, cols):
        if grid[0][j] == 0:
            dp[0][j] = dp[0][j - 1]
    for i in range(1, rows):
        if grid[i][0] == 0:
            dp[i][0] = dp[i - 1][0]

    # Fill in the rest of the dp table from top-left to bottom-right.
    for i in range(1, rows):
        for j in range(1, cols):
            if grid[i][j] == 0:
                dp[i][j] = dp[i - 1][j] + dp[i][j - 1]

    return dp[-1][-1]
