def count_islands(grid):
    if not grid or not grid[0]:
        return 0
    n_rows = len(grid)
    n_cols = len(grid[0])
    visited = [[False for _ in range(n_cols)] for _ in range(n_rows)]
    total = 0

    def is_land(i, j):
        return 0 <= i < n_rows and 0 <= j < n_cols and not visited[i][j] and grid[i][j] == 1

    def flood(i, j):
        queue = [(i, j)]
        visited[i][j] = True
        while queue:
            x, y = queue.pop()
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = x + dx, y + dy
                if is_land(nx, ny):
                    visited[nx][ny] = True
                    queue.append((nx, ny))

    for i in range(n_rows):
        for j in range(n_cols):
            if is_land(i, j):
                total += 1
                flood(i, j)
    return total
