from copy import deepcopy
from collections import deque


def flood_fill(grid, sr, sc, new_value):
    original = grid[sr][sc]
    if original == new_value:
        return deepcopy(grid)
    height = len(grid)
    width = len(grid[0])
    queue = deque()
    queue.append((sr, sc))
    while queue:
        r, c = queue.popleft()
        grid[r][c] = new_value
        for dr, dc in (-1, 0), (1, 0), (0, -1), (0, 1):
            nr, nc = r + dr, c + dc
            if 0 <= nr < height and 0 <= nc < width and grid[nr][nc] == original:
                queue.append((nr, nc))
    return grid
