def parse_url_parts(url):
    scheme_end = url.find('://')
    if scheme_end == -1:
        scheme_end = 0
        scheme = url
    else:
        scheme = url[:scheme_end]
        url = url[scheme_end + 3:]
    host_end = url.find('/')
    if host_end == -1:
        host_end = url.find('?')
    if host_end == -1:
        host = url
        path = ''
        query = ''
    else:
        host = url[:host_end]
        url_tail = url[host_end:]
        if url_tail.startswith('?'):
            path = ''
            query = url_tail[1:]
        else:
            slash_pos = url_tail.find('/')
            if slash_pos == -1:
                path = url_tail
                query = ''
            else:
                path = url_tail[:slash_pos]
                query = url_tail[slash_pos + 1:]
        if not path.startswith('/'):
            path = ''
        return {'scheme': scheme, 'host': host, 'path': path, 'query': query}
