    parts = url.split('://')
    if len(parts) < 2:
        return {'scheme': '', 'host': '', 'path': '', 'query': ''}
    scheme, rest = parts[0], parts[1]
    at_index = rest.find('/')
    if at_index < 0:
        at_index = rest.find('?')
        if at_index < 0:
            host = rest
            path = ''
            query = ''
        else:
            host = rest[:at_index]
            path = ''
            query = rest[at_index + 1:]
    else:
        host = rest[:at_index]
        rest = rest[at_index:]
        quest_index = rest.find('?')
        if quest_index < 0:
            quest_index = len(rest)
        path = rest[:quest_index]
        query = rest[quest_index + 1:]
    return {'scheme': scheme, 'host': host, 'path': path, 'query': query}
