def pedestrian_crossing_ticks(arrivals, red_duration, green_duration):
    cycle = red_duration + green_duration
    result = []
    for t in arrivals:
        cycle_start = (t // cycle) * cycle
        red_end = cycle_start + red_duration
        if t < red_end:
            result.append(t)
        else:
            result.append((cycle_start + red_duration) % cycle)
            if result[-1] == 0:
                result[-1] = cycle
    return result
