def traffic_light_log(n_ticks, durations):
    red, green, yellow = durations
    if n_ticks == 0:
        return []
    if red == green == yellow:
        return ['RED', 'GREEN', 'YELLOW'][:n_ticks]
    tick = 0
    log = []
    while tick < n_ticks:
        if tick < red:
            log.append('RED')
        elif tick < red + green:
            log.append('GREEN')
        else:
            log.append('YELLOW')
        tick += 1
    return log
