def robot_vacuum_cleaned(commands, obstacles):
    """Compute the distinct cells cleaned by the robot after all commands."""
    cells = [(0, 0)]                   # Starting cell
    direction = 'N'                   # Facing north
    x, y = 0, 0
    for cmd in commands:
        if cmd == 'L':
            direction = {'N': 'W', 'W': 'S', 'S': 'E', 'E': 'N'}[direction]
        elif cmd == 'R':
            direction = {'N': 'E', 'E': 'S', 'S': 'W', 'W': 'N'}[direction]
        elif cmd == 'F':
            dx, dy = 0, 1
            if direction == 'E':
                dx, dy = 1, 0
            elif direction == 'S':
                dx, dy = 0, -1
            elif direction == 'W':
                dx, dy = -1, 0
            if (x + dx, y + dy) not in obstacles:
                x += dx
                y += dy
                cells.append((x, y))
    return len(set(cells))
```

