def pedestrian_crossing_ticks(arrivals, red_duration, green_duration):
    full_cycle = red_duration + green_duration
    answer = []
    for t, arrival in enumerate(arrivals):
        remainder = arrival % full_cycle
        if remainder < red_duration:
